{
  "classifications": [
    {
      "document_id": "4207",
      "label": "0",
      "explanation": "The senator is writing a letter and hosting meetings to urge the Department of Homeland Security to consider a proposed levee plan. Since no concrete outcome has been secured yet, this represents active advocacy and appeals without a secured outcome, which is excluded from credit-claiming under the negative clarification."
    },
    {
      "document_id": "2869",
      "label": "0",
      "explanation": "The senator is expressing support for amendments on Iraq and explaining his legislative vote. Explaining a legislative vote and expressing a general policy stance are explicitly excluded from credit-claiming under the negative clarification."
    },
    {
      "document_id": "4774",
      "label": "0",
      "explanation": "The senator is writing a letter to conference committee leaders urging them to keep his amendment in the final version of the bill. Because the final bill has not yet passed into law, this represents an ongoing legislative appeal without a final, secured outcome, which is excluded under the negative clarification."
    },
    {
      "document_id": "4122",
      "label": "0",
      "explanation": "This press release focuses on the senators holding a committee hearing and conducting an ongoing investigation into Medicaid providers. Under the negative clarification, standard committee oversight discussions and ongoing investigations are excluded from credit-claiming."
    },
    {
      "document_id": "1749",
      "label": "0",
      "explanation": "The senator is signing on as an original cosponsor of a newly introduced bill. According to the negative clarification, merely introducing or cosponsoring a new bill that has not yet passed does not constitute credit-claiming."
    },
    {
      "document_id": "4022",
      "label": "0",
      "explanation": "The senator is introducing a new bill ('Medicare for All') and speaking on the healthcare crisis. This is a direct match to one of the negative examples in the codebook, representing position-taking on a bill that has not passed."
    },
    {
      "document_id": "4508",
      "label": "1",
      "explanation": "The senator claims that FEMA's decision to move temporary housing trailers to his state directly follows his personal appeal to the President. This counts as credit-claiming because he is claiming responsibility for securing a specific, completed material benefit for his hurricane-impacted constituents."
    },
    {
      "document_id": "4184",
      "label": "0",
      "explanation": "The senator is co-sponsoring a pending legislative amendment to a budget resolution that has not yet passed. This represents position-taking and ongoing legislative efforts, which are excluded under the negative clarification."
    },
    {
      "document_id": "1257",
      "label": "1",
      "explanation": "This is a positive example from the codebook. Senator DeWine announces a local firefighting grant and explicitly claims credit for writing and passing the underlying FIRE Act that established the grant program."
    },
    {
      "document_id": "805",
      "label": "1",
      "explanation": "Senator Shelby, a member of the Senate Appropriations Committee, announces a federal grant awarded to a fire department in his home state. Standard press releases announcing federal grants awarded to the senator's state are explicitly included as credit-claiming in the clarification."
    },
    {
      "document_id": "1325",
      "label": "0",
      "explanation": "The senator is expressing concern over the judicial nominations process and criticizing the opposing party's tactics. This is classified as position-taking and partisan criticism, which is excluded from credit-claiming under the negative clarification."
    },
    {
      "document_id": "1897",
      "label": "0",
      "explanation": "The senator is expressing his stance on a pending energy bill and threatening a filibuster if it is not modified. This is a policy stance and legislative positioning, not a claim of a completed positive outcome."
    },
    {
      "document_id": "4295",
      "label": "0",
      "explanation": "The senator is introducing a new piece of legislation to modify the Medicaid formula. Although she references a past temporary funding change, the primary purpose of the text is introducing a bill that has not yet passed, which represents position-taking under the negative clarification."
    },
    {
      "document_id": "794",
      "label": "1",
      "explanation": "Senator Bond explicitly claims credit for co-authoring the passed federal highway bill, which is delivering over $4 billion (including $1 billion in new money) in transportation infrastructure funding to his state."
    },
    {
      "document_id": "4677",
      "label": "0",
      "explanation": "This press release focuses on a subcommittee oversight hearing where the senator asks questions, receives updates on military construction, and expresses support for funding. Standard committee oversight discussions and general expressions of support are excluded under the negative clarification."
    },
    {
      "document_id": "42",
      "label": "0",
      "explanation": "The senators are announcing a compromise agreement on a piece of legislation that is being introduced today. Because the bill has not yet passed into law, this represents ongoing legislative negotiations and position-taking, not a completed outcome."
    },
    {
      "document_id": "2335",
      "label": "0",
      "explanation": "The main focus of this press release is promoting an essay contest for Father's Day. Under the negative clarification, purely symbolic events, tributes, and promotions are excluded from credit-claiming."
    },
    {
      "document_id": "1927",
      "label": "1",
      "explanation": "Senator Snowe announces that $8.1 million in funding for the Portsmouth Naval Shipyard has been secured in an appropriations bill that passed the Senate, explicitly noting that she and Senator Collins requested the funding."
    },
    {
      "document_id": "3252",
      "label": "1",
      "explanation": "Senator Nelson announces the successful passage of his amendment to the Agriculture Appropriations bill, claiming credit for a legislative policy change that directly benefits cattle producers in his state and nationwide."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "3534",
      "label": "0",
      "explanation": "Senator Domenici credits President Bush for taking steps to address gas prices and expresses a general policy stance. He does not claim any personal or joint responsibility for securing a specific, positive outcome."
    },
    {
      "document_id": "1862",
      "label": "1",
      "explanation": "Senators Baucus and Tester explicitly claim credit for securing $12.5 million in federal funding for vital military projects in Butte, Montana, within the Defense Appropriations Bill."
    },
    {
      "document_id": "871",
      "label": "0",
      "explanation": "Senator Salazar is questioning the Secretary of the Interior and criticizing the administration's budget cuts. According to the negative clarification, criticizing the administration and participating in standard committee oversight discussions do not qualify as credit-claiming."
    },
    {
      "document_id": "2675",
      "label": "0",
      "explanation": "Senators Dodd and Lieberman are detailing meetings with BRAC Commissioners to advocate against closing a local base. Since no final positive outcome has been secured yet ('until we reach the finish line... our work isn't done'), this represents active advocacy rather than credit-claiming."
    },
    {
      "document_id": "3744",
      "label": "1",
      "explanation": "The text contains a reference to a past successful policy achievement that the senator enacted ('Several years ago the Centers for Disease Control and Prevention at Senator Inouyes request established a small occupational health center...'). The clarification explicitly states that references to past successful achievements are included in credit-claiming."
    },
    {
      "document_id": "2627",
      "label": "1",
      "explanation": "Senator Talent announces that the Senate approved his request for $1.5 million for a health research center, and university leaders explicitly thank him for securing the funding. This falls under securing federal funding for a state project."
    },
    {
      "document_id": "3501",
      "label": "0",
      "explanation": "Senator Tester is expressing disappointment about a proposed Air Force cut and stating his intention to fight it. This represents position-taking and advocacy rather than a secured positive outcome."
    },
    {
      "document_id": "3560",
      "label": "1",
      "explanation": "This is a standard press release announcing federal HUD grants awarded to the senator's state. The clarification notes that standard press releases announcing federal grants awarded to the senator's state are included as credit-claiming."
    },
    {
      "document_id": "3477",
      "label": "0",
      "explanation": "Senator Cornyn is announcing the Senate's confirmation of a nominee. This represents standard legislative duties and does not involve securing a material benefit like funding, passed policy changes, or local projects."
    },
    {
      "document_id": "1747",
      "label": "1",
      "explanation": "Senator Byrd claims credit for his provision in the Defense Authorization Bill that boosts federal funding for the Youth ChalleNGe program, and references his past role in creating the program in 1991. Both aspects satisfy the definition of credit-claiming."
    },
    {
      "document_id": "3729",
      "label": "0",
      "explanation": "Senator Grassley announces a temporary appointment/nomination of an interim U.S. Attorney. This is a standard political announcement and does not constitute securing a material, positive policy or funding outcome."
    },
    {
      "document_id": "1118",
      "label": "0",
      "explanation": "Senator Carper is explaining a legislative vote on a constitutional amendment and expressing a general policy stance. The negative clarification explicitly excludes explaining a legislative vote or expressing a general policy stance."
    },
    {
      "document_id": "4531",
      "label": "0",
      "explanation": "Senators Thune and Clinton are introducing new legislation. According to the negative clarification, introducing or cosponsoring a new bill that has not yet passed does not qualify as credit-claiming."
    },
    {
      "document_id": "3845",
      "label": "0",
      "explanation": "Senator Bayh is expressing a general policy stance regarding OPEC and advocating for a bill he has introduced which has not yet passed. This represents position-taking."
    },
    {
      "document_id": "2026",
      "label": "0",
      "explanation": "Senator Leahy announces that a bill has passed the Judiciary Committee and is moving to the full Senate. Because the bill has not yet passed the full legislature into law, it is not a completed material benefit under the negative clarification."
    },
    {
      "document_id": "1230",
      "label": "1",
      "explanation": "Senators Hatch and Harkin highlight their active role as the principal authors of the Dietary Supplement Health and Education Act (DSHEA) of 1994, which successfully authorized the FDA to write the regulations announced. This constitutes a reference to a past successful policy achievement they enacted."
    },
    {
      "document_id": "817",
      "label": "0",
      "explanation": "Senator Collins is testifying in support of a bill she is sponsoring that has not yet passed. The negative clarification excludes sponsoring bills that have not yet passed or active advocacy without a secured outcome."
    },
    {
      "document_id": "1177",
      "label": "0",
      "explanation": "Senators Pryor and Chambliss write letters calling on the Air Force to reimburse subcontractors. Since this is an ongoing dispute with no secured resolution, it represents active advocacy, not credit-claiming, matching the negative example in the codebook."
    },
    {
      "document_id": "3271",
      "label": "1",
      "explanation": "Senator Crapo claims credit for authoring the Financial Services Regulatory Relief Act of 2006, which has successfully achieved unanimous Senate passage, representing a significantly advanced material benefit."
    },
    {
      "document_id": "1320",
      "label": "1",
      "explanation": "Senator Hutchison explicitly claims credit for helping to secure $3 billion in emergency federal funding for drought and wildfire relief for Texas and the nation."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "57",
      "label": "0",
      "explanation": "Senator Kennedy is introducing legislation (the Human Cloning Ban and Stem Cell Research Protection Act). According to the negative clarification, introducing or cosponsoring a new bill that has not yet passed is not credit-claiming."
    },
    {
      "document_id": "2318",
      "label": "1",
      "explanation": "Senator Durbin claims credit for past successful policy achievements, specifically stating: 'I helped secure an expedited environmental review from the federal government and facilitated the return of the project to the national priority list for federal funding.' This represents a completed material benefit secured for his constituents."
    },
    {
      "document_id": "3482",
      "label": "1",
      "explanation": "Senators Mikulski and Cardin announce a $294,980 SAFER grant for Allegany County. Standard press releases announcing federal grants awarded to the senator's state are explicitly included under the clarification."
    },
    {
      "document_id": "597",
      "label": "0",
      "explanation": "Senator Lugar is presenting a local community health and fitness award bearing his name. This is a community event/ceremonial action and does not involve securing a specific material outcome or funding from the federal government."
    },
    {
      "document_id": "656",
      "label": "0",
      "explanation": "This text contains partisan position-taking and criticism of the Bush Administration's handling of port security. It does not claim any secured positive policy outcome, which matches the negative example in the codebook."
    },
    {
      "document_id": "4771",
      "label": "1",
      "explanation": "Senator Clinton highlights her past active role in securing a material benefit for her state, noting that in 2005 she 'played a key role... in preventing the removal of four C 130 Aircraft'. This refers to a past successful policy achievement she enacted/helped secure, which is covered under the clarification."
    },
    {
      "document_id": "918",
      "label": "0",
      "explanation": "The text merely announces a town hall meeting in Greeley, Colorado. This does not claim any specific government benefit or outcome."
    },
    {
      "document_id": "3577",
      "label": "0",
      "explanation": "Senator Sarbanes expresses concerns and criticizes FEMA's implementation of flood insurance reforms. This is a combination of committee oversight and position-taking, and does not claim a completed or secured positive outcome."
    },
    {
      "document_id": "4585",
      "label": "1",
      "explanation": "Senator Schumer announces federal fire grants totaling over $134,000 for Westchester County fire departments. Standard press releases announcing federal grants awarded to the senator's state are included in the definition of credit-claiming."
    },
    {
      "document_id": "89",
      "label": "1",
      "explanation": "Senator Dorgan explicitly claims credit for authoring the legislation that was signed into law creating the National Center designation for Bismarck State College, representing a completed material benefit for his state."
    },
    {
      "document_id": "240",
      "label": "0",
      "explanation": "Senator Ensign is expressing a policy stance and reacting to the confirmation of Michael Chertoff. Explaining a legislative vote or expressing a general policy stance does not count as credit-claiming."
    },
    {
      "document_id": "453",
      "label": "0",
      "explanation": "Senator Nelson explains his legislative vote against two resolutions regarding troop withdrawal from Iraq and states his policy positions. Under the negative clarification, explaining a legislative vote or expressing a general policy stance is excluded."
    },
    {
      "document_id": "4208",
      "label": "0",
      "explanation": "Senators Dorgan and Lott are announcing the introduction of a new bipartisan bill. Because the bill has not yet passed, this falls under the negative clarification as position-taking."
    },
    {
      "document_id": "1957",
      "label": "1",
      "explanation": "Senators Dodd and Lieberman announce a federal grant of $2,250,000 for Bradley International Airport, which is a standard federal grant announcement for their state."
    },
    {
      "document_id": "2807",
      "label": "0",
      "explanation": "Senator Lincoln is recognizing a state agricultural proclamation and highlighting her seat on the Agriculture Committee. This represents symbolic support and position-taking rather than securing a concrete material government outcome."
    },
    {
      "document_id": "3659",
      "label": "0",
      "explanation": "Senator Clinton welcomes an advisory board's recommendation to compensate former nuclear workers. Since this is an ongoing administrative process (a recommendation that has not yet been final-approved by the Secretary) and she is not claiming to have secured the final outcome, it does not qualify as credit-claiming."
    },
    {
      "document_id": "967",
      "label": "1",
      "explanation": "Senator Shelby, a member of the Senate Appropriations Committee, announces that over $3 million in federal funds will be released for childcare programs in Alabama. This is a standard federal funding announcement."
    },
    {
      "document_id": "3687",
      "label": "1",
      "explanation": "Senator Bingaman announces that New Mexico State University has been awarded $599,691 in federal funding from the USDA, which is a standard federal grant announcement."
    },
    {
      "document_id": "50",
      "label": "0",
      "explanation": "Senator Reid criticizes the Bush Administration's stance on global warming. This is partisan position-taking with no credit claimed for a positive material benefit."
    },
    {
      "document_id": "1021",
      "label": "1",
      "explanation": "Senators Wyden and Smith announce that the Senate Appropriations Committee has approved funding for the Pacific Coast Salmon Recovery Fund and OSU. Gaining committee approval for state funding represents a significantly advanced material benefit under the clarification."
    }
  ]
}
